// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }

    function testFuzz_property(address target, bool freeze) public {
        vm.assume(target != address(0));
        vm.prank(c.owner());
        c.freezeAccount(target, freeze);
        // General rule: frozenAccount[target] must equal the requested freeze flag.
        assertTrue(c.frozenAccount(target) == freeze, "frozenAccount must match the requested flag");
    }
}
